/** @format */

$(document).ready(function () {
  // 1. Password Visibility Toggle
  $('#togglePasswordBtn').on('click', function () {
    var $passInput = $('#loginPassword');
    var $passIcon = $('#togglePasswordIcon');
    var isPassword = $passInput.attr('type') === 'password';

    $passInput.attr('type', isPassword ? 'text' : 'password');
    $passIcon.toggleClass('bi-eye bi-eye-slash');
  });

  // 2. Request Location Immediately on Page Load
  requestUserLocation();

  function requestUserLocation(callback) {
    var $geoText = $('#geoStatusText');
    var $geoBox = $('#geoStatusBox');
    var $geoIcon = $('#geoStatusIcon');

    if (!navigator.geolocation) {
      if ($geoText.length) {
        $geoText.html('<span class="text-danger fw-semibold">Geolocation unsupported.</span>');
      }
      if (typeof callback === 'function') callback(false);
      return;
    }

    if ($geoText.length) {
      $geoBox.removeClass('border-danger border-success').addClass('border-warning');
      $geoIcon.attr('class', 'bi bi-hourglass-split text-warning fs-6');
      $geoText.html('<span class="text-warning fw-semibold">Please allow location access...</span>');
    }

    navigator.geolocation.getCurrentPosition(
      function (pos) {
        var lat = pos.coords.latitude;
        var lon = pos.coords.longitude;
        var accuracy = Math.round(pos.coords.accuracy);

        $('#loginLatitude').val(lat);
        $('#loginLongitude').val(lon);

        if ($geoText.length) {
          $geoText.html('<span class="text-secondary"><i class="bi bi-hourglass-split me-1"></i>Resolving address...</span>');
        }

        // Cache check: Don't spam Nominatim if user already fetched coordinates this session
        var cacheKey = 'nominatim_' + lat.toFixed(3) + '_' + lon.toFixed(3);
        var cachedAddress = sessionStorage.getItem(cacheKey);

        if (cachedAddress) {
          applyLocationSuccess(cachedAddress, accuracy, callback);
          return;
        }

        // Exact reverse geocode pattern from attendance.js
        $.ajax({
          url: 'https://nominatim.openstreetmap.org/reverse?format=json&lat=' + lat + '&lon=' + lon,
          type: 'GET',
          headers: { 'Accept-Language': 'en' },
          timeout: 8000
        })
          .done(function (data) {
            var address = (data && data.display_name) ? data.display_name : 'Unknown Location';
            sessionStorage.setItem(cacheKey, address);
            applyLocationSuccess(address, accuracy, callback);
          })
          .fail(function () {
            // If rate-limited (429) or CORS-blocked, fall back gracefully to a clean name
            var fallback = 'Office / Verified GPS';
            $('#loginLocationName').val(fallback);

            if ($geoText.length) {
              $geoBox.removeClass('border-warning border-danger').addClass('border-success');
              $geoIcon.attr('class', 'bi bi-check-circle-fill text-success fs-6');
              $geoText.html('<span class="text-success"><i class="bi bi-geo-alt-fill me-1 text-danger"></i>Location acquired (±' + accuracy + 'm)</span>');
            }

            if (typeof callback === 'function') callback(true);
          });
      },
      function (err) {
        $('#loginLatitude').val('');
        $('#loginLongitude').val('');
        $('#loginLocationName').val('');

        var errorMsg = 'Location permission is recommended for sign-in.';
        switch (err.code) {
          case err.PERMISSION_DENIED:
            errorMsg = 'Location permission denied. You can still sign in.';
            break;
          case err.POSITION_UNAVAILABLE:
            errorMsg = 'GPS unavailable. You can still sign in.';
            break;
          case err.TIMEOUT:
            errorMsg = 'Location request timed out. You can still sign in.';
            break;
        }

        if ($geoText.length) {
          $geoBox.removeClass('border-warning border-success').addClass('border-danger');
          $geoIcon.attr('class', 'bi bi-shield-x text-danger fs-6');
          $geoText.html('<span class="text-danger fw-semibold"><i class="bi bi-shield-x me-1"></i>' + errorMsg + '</span>');
        }

        $.toast({
          message: errorMsg,
          status: 'warning'
        });

        if (typeof callback === 'function') callback(false);
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 60000 // Reuse cached device coordinates within 1 minute
      }
    );
  }

  function applyLocationSuccess(address, accuracy, callback) {
    var $geoText = $('#geoStatusText');
    var $geoBox = $('#geoStatusBox');
    var $geoIcon = $('#geoStatusIcon');

    $('#loginLocationName').val(address);

    if ($geoText.length) {
      $geoBox.removeClass('border-warning border-danger').addClass('border-success');
      $geoIcon.attr('class', 'bi bi-check-circle-fill text-success fs-6');
      $geoText.html('<span class="text-success"><i class="bi bi-geo-alt-fill me-1 text-danger"></i>' + address + ' (±' + accuracy + 'm)</span>');
    }

    if (typeof callback === 'function') callback(true);
  }

  // 3. Login Form Submission (Permits login even if location was not allowed)
  $('#loginForm').on('submit', function (s) {
    s.preventDefault();

    var $btn = $(this).find('button[type="submit"]');
    var lat = $('#loginLatitude').val();
    var lng = $('#loginLongitude').val();

    if (!lat || !lng) {
      $.toast({
        message: 'Proceeding without verified GPS coordinates.',
        status: 'warning'
      });
    }

    sendLoginRequest($btn);
  });

  // 4. API Request Handler
  function sendLoginRequest($btn) {
    $btn.prop('disabled', true);
    var formData = $('#loginForm').getFormData();

    $.api({
      url: 'check/login',
      type: 'POST',
      data: formData,
      form: '#loginForm',
      onSuccess: function (res) {
        $.toast({
          message: res.message || 'Logging you in...',
          status: 'success'
        });

        setTimeout(function () {
          var routeTo = (res.data && res.data.routeTo) || res.routeTo || 'dashboard';
          window.location.href = $.baseUrl + '#/' + routeTo;
        }, 1500);
      },
      onError: function (res) {
        $btn.prop('disabled', false);
        $('#loginForm').resetFormAndFocus();
        $.toast({
          message: res.message || 'Invalid credentials',
          status: 'danger'
        });
      }
    });
  }
});